/// <summary>
/// designed from AVA
/// </summary>
[ExtensionOf(formStr(PriceDiscTable))]
final class AVAPriceDiscTableFrm_Extension
{
    public boolean icAgreement;

}

Method.Source:
/// <summary>
/// designed from AVA
/// </summary>
public void init()
{
    Args    locArgs;
    boolean locSetQueryRange;

    locArgs = this.args();

    next init();

    PriceDiscTable_ds.object(fieldNum(PriceDiscTable,AVAGraduatedPrice)).visible(relationType == PriceType::PricePurch);
    avaCalculationDate.dateValue(DateTimeUtil::getToday(DateTimeUtil::getUserPreferredTimeZone()));
    /*
    if (locArgs.menuItemName() != menuItemDisplayStr(RetailPricingDiscountActiveTradeAgreement))
    {
    AVAShowOnlyActual.checked(true);
    this.AVASetQueryRanges();
    }
    */

    if (locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_PricePurchAction)   // EcoResProductDetailsExtended - VendTable - Price
        && locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_PricePurchAction))   // VendTable - Price
    {
        AVACalculationDate.visible(true);
    }

    // EcoResProductDetailsExtended
    if (    locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_PricePurchAction)   // EcoResProductDetailsExtended - VendTable - Price
        ||  locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_LineDiscPurchAction)// EcoResProductDetailsExtended - VendTable - Price disc
        ||  locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_PurchAction)        // EcoResProductDetailsExtended - VendTable - Agreement
        )
    {
        AVAPriceWithCharge.visible(true);
        AVAShowOnlyActual.checked(true);
        locSetQueryRange = true;
    }
    else if (  locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_PriceSalesAction)   // EcoResProductDetailsExtended - CustTable - Price
        ||  locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_LineDiscSalesAction)// EcoResProductDetailsExtended - CustTable - Price disc
        ||  locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_SalesAction)        // EcoResProductDetailsExtended - CustTable - Agreement
        )
    {
        AVAShowOnlyActual.checked(true);
        locSetQueryRange = true;
    }
    // VendTable
    if (    locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_PricePurchAction)   // VendTable - Price
        ||  locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_LineDiscPurchAction)// VendTable - Price disc
        ||  locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_PurchAction)        // VendTable - Agreement
        )
    {
        AVAShowOnlyActual.checked(true);
        locSetQueryRange = true;
    }

    // IC - Areements
    if (locArgs.menuItemName() == menuItemDisplayStr(NDXPriceDiscTable_ICSales))   
    {
        icAgreement = true; 
    }

    // CustTable
    if (    locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_PriceSales)         // CustTable - Price
        ||  locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_LineDiscSales)      // CustTable - Price disc
        ||  locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_Sales)              // CustTable - Agreement
        ||  icAgreement
        )
    {
        AVAShowOnlyActual.checked(true);
        locSetQueryRange = true;
    }
    // PriceDiscGroup
    if (    locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_Sales)              // PriceDiscGroup - CustTable - Agreement
        ||  locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_LineDiscSales)      // PriceDiscGroup - CustTable - Price disc
        ||  locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_Purch)              // PriceDiscGroup - VendTable - Agreement
        ||  locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_LineDiscPurch)      // PriceDiscGroup - VendTable - Price disc
        )
    {
        AVAShowOnlyActual.checked(true);
        locSetQueryRange = true;
    }
    // StandardVendor
    if (    locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_PricePurchAction)   // StandardVendor - Price
        ||  locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_LineDiscPurchAction)// StandardVendor - Price disc
        ||  locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_PurchAction)        // StandardVendor - Agreement
        ||  locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_Purch)              // StandardVendor - VendTable - Agreement
        ||  locArgs.menuItemName() == menuItemDisplayStr(PriceDiscTable_LineDiscPurch)      // StandardVendor - VendTable - Price disc
        )
    {
        AVAStandardVendor.visible(true);
        //AVAStandardVendor.checked(true);
        locSetQueryRange = true;
    }

    if(locSetQueryRange == true)
    {
        this.AVASetQueryRanges();
    }         
}

/// <summary>
///     AVA <c>setQueryRanges</c> method.
/// </summary>
public void avaSetQueryRanges()
{
    QueryBuildDataSource    locQbds;
    QueryBuildRange         locQbrDateFrom;
    QueryBuildRange         locQbrDateTo;
    QueryBuildDataSource    locQbdsInventTable;
    QueryBuildRange         locQbrPrimaryVendorId;
    str                     formatedDateRange;

    locQbds         = PriceDiscTable_ds.queryBuildDataSource();
    //locQbrDate  = locQbds.addRange(fieldNum(PriceDiscTable, FromDate));
    locQbrDateFrom  = SysQuery::findOrCreateRange(locQbds, fieldNum(PriceDiscTable, FromDate));
    if(AVAShowOnlyActual.checked())
    {
        formatedDateRange = strFmt('(((%1 <= %3) || (%1 == %4)) && ((%2 >= %3) || (%2 == %4)))',    fieldStr(PriceDiscTable, FromDate),
                                                                                                    fieldStr(PriceDiscTable, ToDate),
                                                                                                    date2StrXpp(SysQueryRangeUtil::currentDate()),
                                                                                                    date2StrXpp(dateNull())                         );
        locQbrDateTo = SysQuery::findOrCreateRange(locQbds, fieldNum(PriceDiscTable, ToDate));
        locQbrDateTo.value(sysQuery::valueUnlimited());
    }
    else
    {
        formatedDateRange = sysQuery::valueUnlimited();
    }
    locQbrDateFrom.value(formatedDateRange);
    //locQbrDateFrom.status(RangeStatus::Hidden); // reactivate possibility to change filter

    locQbdsInventTable = InventTable_DS.queryBuildDataSource();

    if(AVAStandardVendor.checked())
    {
        locQbdsInventTable.joinMode(JoinMode::InnerJoin);
        locQbdsInventTable.addLink(fieldNum(PriceDiscTable, AccountRelation), fieldNum(InventTable, PrimaryVendorId));
        locQbrPrimaryVendorId = SysQuery::findOrCreateRange(locQbdsInventTable, fieldNum(InventTable, PrimaryVendorId));
        locQbrPrimaryVendorId.value(sysQuery::valueNot(''));
    }
    else
    {
        locQbdsInventTable.joinMode(JoinMode::OuterJoin);
        locQbdsInventTable.clearLinks();
        locQbdsInventTable.addLink(fieldNum(PriceDiscTable, ItemRelation), fieldNum(InventTable, ItemId));
        locQbrPrimaryVendorId = SysQuery::findOrCreateRange(locQbdsInventTable, fieldNum(InventTable, PrimaryVendorId));
        locQbrPrimaryVendorId.value(sysQuery::valueUnlimited());


    }

    if(icAgreement)
    {
        this.initPriceDiscGroup();
        if(this.args().record() != null && this.args().dataset() == tableNum(CustTable))
        {
            custTable = this.args().record();
            locQbrPrimaryVendorId = SysQuery::findOrCreateRange(locQbds, fieldNum(PriceDiscTable, AccountRelation));
            locQbrPrimaryVendorId.value(custTable.AccountNum);
        }
    }

    locQbrPrimaryVendorId.status(RangeStatus::Hidden);
}

/// <summary>
///     AVA <c>setQueryRanges</c> method for active record at provided date.
/// </summary>
public void avaSetActiveQueryRanges()
{
    QueryBuildDataSource    locQbds;
    QueryBuildRange         locQbrDateFrom;
    QueryBuildRange         locQbrDateTo;
    str                     formatedDateRange;

    locQbds         = avaPriceDiscTable_ds.queryBuildDataSource();
    locQbrDateFrom  = SysQuery::findOrCreateRange(locQbds, fieldNum(PriceDiscTable, FromDate));
    formatedDateRange = strFmt('(((%1 <= %3) || (%1 == %4)) && ((%2 >= %3) || (%2 == %4)))',    fieldStr(PriceDiscTable, FromDate),
                                                                                                fieldStr(PriceDiscTable, ToDate),
                                                                                                date2StrXpp(AVACalculationDate.dateValue()),
                                                                                                date2StrXpp(dateNull()) );

    locQbrDateFrom.value(formatedDateRange);
    locQbrDateTo = SysQuery::findOrCreateRange(locQbds, fieldNum(PriceDiscTable, ToDate));
    locQbrDateTo.value(sysQuery::valueUnlimited());
}

/// <summary>
///     AVA <c>avaExecuteQueryPriceDiscTableDS</c> method.
/// </summary>
public void avaExecuteQueryPriceDiscTableDS()
{
    FormDataSource  locPriceDiscTableDS;

    locPriceDiscTableDS = PriceDiscTable_DS;

    locPriceDiscTableDS.executeQuery();
}

/// <summary>
/// Refreshes the associated HK FormParts
/// </summary>
public void avaRefreshHKFormParts()
{
    AVAPriceDiscTable_ds.executeQuery();

    PartList        avaPartList = new PartList(this);
    FormRun         avaHKPurchPriceInfo = avaPartList.getPartControlByFormName(formStr(AVAHKPurchPriceInfo)).getPartFormRun();
    FormRun         avaHKMarkupInfo     = avaPartList.getPartControlByFormName(formStr(AVAHKMarkupInfo)).getPartFormRun();

    avaHKPurchPriceInfo.dataSource().research();
    avaHKMarkupInfo.dataSource().research();
}
